API Gateway / Application Load Balancer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway / Application Load Balancer") {
    Component(tls_termination, "TLS Termination Engine", "AWS ALB TLS Termination Engine", "Terminates incoming HTTPS connections using TLS 1.3 for payment authorizations and analyst commands.")
    Component(listener_rules, "Listener Rules", "AWS ALB Listener Rules", "Evaluates and routes incoming traffic to the Fraud Scoring Engine or Case Management Service.")
}

Rel(tls_termination, listener_rules, "Decrypts and forwards traffic", "")

@enduml

Amazon ElastiCache Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_elasticache_redis, "Amazon ElastiCache Redis") {
    Component(Feature_Store_Component, "Feature Store Component", "In-Memory Hash/Sorted Sets", "Reads/writes sliding-window aggregates and velocity metrics.")
    Component(Rule_Cache_Component, "Rule Cache Component", "In-Memory KV", "Reads active fraud rules and model thresholds.")
    Component(Session_State_Component, "Session State Component", "In-Memory KV", "Reads/writes analyst session states and workspace locks.")
}

Rel(Feature_Store_Component, Rule_Cache_Component, "Operates within the shared ElastiCache Redis cluster.")
@enduml

Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql, "Amazon Aurora PostgreSQL") {
    Component(Database_Engine, "Database Engine", "Amazon Aurora PostgreSQL 15", "Manages ACID-compliant case data, transaction logs, and multi-AZ replication.")
    Component(PgBouncer_Connection_Pooler, "PgBouncer Connection Pooler", "PgBouncer", "Handles high concurrency, manages persistent connections, and prevents database connection exhaustion.")
}

Rel(PgBouncer_Connection_Pooler, Database_Engine, "Forwards pooled client queries and transactions", "PostgreSQL Wire Protocol")

@enduml

Amazon S3 Immutable Vault.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_s3_immutable_vault, "Amazon S3 Immutable Vault") {
    Component(Vault_Ingestion_Interceptor, "Vault Ingestion Interceptor", "Go on AWS Lambda", "Submits immutable audit logs and case artifacts")
    Component(S3_Object_Lock_Manager, "S3 Object Lock Manager", "AWS S3 Configuration", "Stores objects with retention policies")
    Component(Audit_Verification_Worker, "Audit Verification Worker", "Python on AWS Lambda", "Reads and verifies payload hashes")
    Component(Access_Control_Enforcer, "Access Control Enforcer", "AWS IAM / S3 Bucket Policies", "Enforces strict least-privilege access control")
}

Rel(Vault_Ingestion_Interceptor, S3_Object_Lock_Manager, "Stores objects with retention policies", "S3 API")
Rel(Audit_Verification_Worker, S3_Object_Lock_Manager, "Reads and verifies payload hashes", "S3 API (Read-Only)")

@enduml

Amazon SQS / SNS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon SQS / SNS container

Container_Boundary(amazon_sqs_sns, "Amazon SQS / SNS") {
    Component(Fraud_Event_Topic_Amazon_SNS, "Fraud Event Topic (Amazon SNS)", "Amazon SNS", "Publishes and fans out scoring outcomes to downstream queues.")
    Component(Review_Queue_Amazon_SQS_Standard, "Review Queue (Amazon SQS Standard)", "Amazon SQS Standard", "Buffers and filters review cases for human analysts.")
    Component(Audit_Event_Queue_Amazon_SQS_FIFO, "Audit Event Queue (Amazon SQS FIFO)", "Amazon SQS FIFO", "Guarantees strict ordering for asynchronous audit decision payloads.")
    Component(Audit_Dead_Letter_Queue_Amazon_SQS_FIFO, "Audit Dead-Letter Queue (Amazon SQS FIFO)", "Amazon SQS FIFO", "Captures failed audit log delivery messages for investigation.")
}

Rel(Fraud_Event_Topic_Amazon_SNS, Review_Queue_Amazon_SQS_Standard, "Filters and fans out review cases", "SNS Subscription")

@enduml
